/* Token Radar's dark theme. Five palette values, two radii and two families are the whole style;
   everything else is spacing, a hairline and a type step. No network: no web fonts, no images. */
:root {
  --bg: #0a0f1e;
  --panel: #101a2e;
  --panel-2: #0d1526;
  --ink: #e9eef8;
  --muted: #94a6c2;
  --line: #223250;
  --accent: #38bdf8;
  --gold: #f5b942;
  --up: #34d399;
  --down: #f87171;
  --radius-control: 8px;
  --radius-panel: 14px;
  --font-body: system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-num: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --step-1: 4px;
  --step-2: 8px;
  --step-3: 12px;
  --step-4: 16px;
  --step-5: 24px;
  --step-6: 32px;
  --step-7: 48px;
}

* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 400 15px/1.5 var(--font-body);
  text-wrap: pretty;
}
h1, h2, h3 { margin: 0; letter-spacing: -0.02em; text-wrap: balance; }
h1 { font-size: 30px; line-height: 1.15; font-weight: 650; }
h2 { font-size: 20px; line-height: 1.2; font-weight: 650; }
h3 { font-size: 16px; line-height: 1.25; font-weight: 650; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
a { color: var(--accent); }
.skip {
  position: absolute; left: -999px; top: 0;
  background: var(--accent); color: #06121f; padding: var(--step-2) var(--step-3);
  border-radius: 0 0 var(--radius-control) 0; z-index: 20; font-weight: 600;
}
.skip:focus { left: 0; }

.shell { max-width: 1180px; margin: 0 auto; padding: var(--step-5) var(--step-4) var(--step-7); }
.top {
  display: flex; flex-wrap: wrap; gap: var(--step-3);
  align-items: center; justify-content: space-between;
  padding-bottom: var(--step-4); border-bottom: 1px solid var(--line);
}
.brand { display: flex; align-items: center; gap: var(--step-3); }
.mark {
  width: 34px; height: 34px; border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, var(--accent), #0e7490 55%, #164e63);
  border: 2px solid var(--accent);
  box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.15);
  flex: none;
}
.brand-name { font-weight: 750; letter-spacing: 0.08em; text-transform: uppercase; font-size: 17px; }
.top-meta { display: flex; flex-wrap: wrap; gap: var(--step-2); color: var(--muted); font-size: 13px; }
.top-meta span { border: 1px solid var(--line); border-radius: 999px; padding: 3px 10px; background: var(--panel-2); }

.lede { display: grid; grid-template-columns: 1.5fr 1fr; gap: var(--step-5); padding: var(--step-6) 0 var(--step-5); }
.lede p { color: var(--muted); margin-top: var(--step-3); max-width: 56ch; }
.facts { display: grid; grid-template-columns: 1fr 1fr; gap: var(--step-3); }
.fact {
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius-panel);
  padding: var(--step-3) var(--step-4);
}
.fact span { display: block; color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; }
.fact b { font: 650 22px/1.3 var(--font-num); color: var(--ink); }
.fact b.gold { color: var(--gold); }

.controls {
  display: flex; flex-wrap: wrap; gap: var(--step-3); align-items: end;
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius-panel);
  padding: var(--step-4); margin-bottom: var(--step-4);
}
.field { display: flex; flex-direction: column; gap: var(--step-1); }
.field label, .field .sub { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; }
.field input, .field select {
  background: var(--panel-2); border: 1px solid var(--line); border-radius: var(--radius-control);
  padding: 9px 12px; min-width: 220px; color: var(--ink);
}
.field input:focus, .field select:focus { outline: 2px solid var(--accent); outline-offset: 1px; }
.tabs { display: flex; gap: var(--step-1); }
.tabs button {
  background: var(--panel-2); border: 1px solid var(--line); border-radius: var(--radius-control);
  padding: 9px 14px; color: var(--muted);
}
.tabs button[aria-pressed="true"] { background: var(--accent); border-color: var(--accent); color: #06121f; font-weight: 650; }
.count { margin-left: auto; color: var(--muted); font-size: 13px; align-self: center; }

.panel {
  background: var(--panel); border: 1px solid var(--line);
  border-radius: var(--radius-panel); margin-bottom: var(--step-5);
}
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
caption { text-align: left; padding: var(--step-4); color: var(--muted); caption-side: top; }
th, td { padding: 10px 14px; text-align: left; border-bottom: 1px solid var(--line); vertical-align: middle; }
thead th { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; }
tbody tr:last-child td { border-bottom: none; }
tbody tr { cursor: pointer; }
tbody tr:hover { background: rgba(56, 189, 248, 0.07); }
tbody tr[data-selected="true"] { background: rgba(56, 189, 248, 0.12); }
tbody tr:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
th button { background: none; border: none; padding: 0; color: inherit; font: inherit; text-transform: inherit; letter-spacing: inherit; }
th button:hover { color: var(--ink); }
.num { font-family: var(--font-num); font-variant-numeric: tabular-nums; white-space: nowrap; }
.pos { color: var(--up); }
.neg { color: var(--down); }
.name b { display: block; font-weight: 650; }
.name .sub, .sub { color: var(--muted); font-size: 13px; }
.tag {
  display: inline-block; font-size: 11px; font-weight: 700; letter-spacing: 0.05em;
  color: var(--gold); border: 1px solid rgba(245, 185, 66, 0.5); border-radius: 999px;
  padding: 1px 7px; margin-left: 6px; vertical-align: 1px;
}
.implied { display: flex; align-items: center; gap: var(--step-2); min-width: 170px; }
.implied .bar { flex: 1; height: 6px; background: var(--line); border-radius: 999px; overflow: hidden; }
.implied .bar i { display: block; height: 100%; background: linear-gradient(90deg, var(--accent), var(--gold)); border-radius: 999px; }
.implied .num { color: var(--gold); font-weight: 650; }
.status {
  display: inline-block; font-size: 12px; font-weight: 650; color: var(--accent);
  border: 1px solid rgba(56, 189, 248, 0.45); border-radius: 999px; padding: 2px 9px; white-space: nowrap;
}
.status.live { color: var(--up); border-color: rgba(52, 211, 153, 0.45); }
.empty { padding: var(--step-6) var(--step-5); text-align: center; }
.empty p { color: var(--muted); margin: var(--step-2) 0 var(--step-4); }
.button {
  background: var(--panel-2); border: 1px solid var(--line); border-radius: var(--radius-control);
  padding: 9px 16px; color: var(--ink);
}
.button.primary { background: var(--accent); border-color: var(--accent); color: #06121f; font-weight: 650; }

.model { padding: var(--step-5); }
.model h2 { margin-bottom: var(--step-2); }
.model p { color: var(--muted); margin-top: var(--step-2); max-width: 78ch; }
.formula {
  font-family: var(--font-num); font-size: 13px; line-height: 1.7; color: var(--ink);
  background: var(--panel-2); border: 1px solid var(--line); border-radius: var(--radius-control);
  padding: var(--step-3) var(--step-4); margin: var(--step-4) 0; overflow-x: auto; white-space: pre-wrap;
  word-break: break-word;
}
.comps { width: 100%; margin-top: var(--step-4); }
.comps td, .comps th { padding: 6px 10px; }
.comps .num { font-size: 13px; }

.detail {
  background: var(--panel); color: var(--ink); border: 1px solid var(--line);
  border-radius: var(--radius-panel); padding: 0; max-width: 720px; width: calc(100% - 32px);
  max-height: calc(100vh - 48px); overflow: auto;
}
.detail::backdrop { background: rgba(4, 8, 18, 0.75); }
.detail-head {
  display: flex; justify-content: space-between; gap: var(--step-4); align-items: start;
  padding: var(--step-5) var(--step-5) 0;
}
.detail-head h2 { font-size: 26px; margin-top: var(--step-1); }
.detail-head .sub { margin-top: var(--step-1); }
.close {
  background: var(--panel-2); border: 1px solid var(--line); border-radius: var(--radius-control);
  padding: 8px 14px; color: var(--ink); flex: none;
}
.detail-section { padding: var(--step-4) var(--step-5) var(--step-5); }
.detail-section h3 { margin-bottom: var(--step-3); }
.equation { display: grid; grid-template-columns: 1fr 1fr; gap: var(--step-2) var(--step-5); }
.equation div { display: flex; justify-content: space-between; gap: var(--step-3); border-bottom: 1px dashed var(--line); padding: 7px 0; }
.equation span { color: var(--muted); }
.equation .num { font-weight: 650; }
.equation .num.gold { color: var(--gold); }
.steps { margin: 0; padding-left: 22px; }
.steps li { margin-bottom: var(--step-3); line-height: 1.55; }
.steps li b { font-weight: 600; }
.steps .cost { display: block; color: var(--muted); font-size: 13px; margin-top: 2px; }
.note {
  background: var(--panel-2); border: 1px solid var(--line); border-radius: var(--radius-control);
  padding: var(--step-3) var(--step-4); color: var(--muted); font-size: 13px; margin-top: var(--step-4);
}
.foot { color: var(--muted); font-size: 13px; padding-top: var(--step-4); border-top: 1px solid var(--line); }
.foot p + p { margin-top: var(--step-2); }

@media (max-width: 760px) {
  .lede { grid-template-columns: 1fr; }
  .equation { grid-template-columns: 1fr; }
  h1 { font-size: 24px; }
  .field input, .field select { min-width: 0; width: 100%; }
  .field { flex: 1 1 100%; }
}
